pages.css:
.content-root{width:100%;height:100%;padding:18px 20px;overflow:hidden;font-family:'Segoe UI',system-ui,sans-serif}
.lesson-split{display:grid;grid-template-columns:48% 52%;height:100%;gap:18px}
.lesson-column{min-width:0;display:flex;flex-direction:column}
.column-heading{font-size:16px;font-weight:800;text-transform:uppercase;letter-spacing:.6px;color:#E2571C;margin:0 0 10px;padding-bottom:8px;border-bottom:2px solid #F5A623}
.words-grid{flex:1;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));align-content:center;gap:10px;padding:8px}
.word-cell{min-height:62px;border:2px solid #dee2e6;border-radius:10px;background:#fff;font-size:22px;font-weight:800;color:#1a1a1a;cursor:pointer;transition:.12s;box-shadow:0 2px 5px rgba(0,0,0,.05)}
.word-cell:hover{border-color:#F5A623}
.word-cell.selected{background:#dc3545;border-color:#dc3545;color:#fff}
.sentences-list{display:flex;flex-direction:column;gap:10px;justify-content:center;flex:1}
.sentence-row{width:100%;text-align:left;padding:16px 16px;border:2px solid #dee2e6;border-radius:10px;background:#fff;color:#1a1a1a;font-family:Georgia,'Times New Roman',serif;font-size:19px;line-height:1.35;cursor:pointer;box-shadow:0 2px 5px rgba(0,0,0,.05)}
.sentence-row:hover{border-color:#F5A623;background:#fffaf1}
.sentence-fullscreen{position:fixed;inset:0;background:rgba(0,0,0,.9);display:none;align-items:center;justify-content:center;z-index:999999;padding:60px}
.sentence-fullscreen.open{display:flex}
.sentence-modal{position:relative;width:min(1100px,92vw);min-height:280px;background:#fff;border-radius:20px;padding:70px 70px 60px;display:flex;align-items:center;justify-content:center;box-shadow:0 20px 70px rgba(0,0,0,.5)}
.sentence-modal-text{font-family:Georgia,'Times New Roman',serif;font-size:clamp(30px,5vw,64px);font-weight:700;line-height:1.25;text-align:center;color:#1a1a1a}
.sentence-close{position:absolute;right:18px;top:14px;width:46px;height:46px;border:0;border-radius:50%;background:#1a1a1a;color:#fff;font-size:32px;line-height:1;cursor:pointer}

pages.js:
const cells = root.querySelectorAll('.word-cell');
cells.forEach(cell => {
  cell.addEventListener('click', () => cell.classList.toggle('selected'));
});

const overlay = document.createElement('div');
overlay.className = 'sentence-fullscreen';
overlay.innerHTML = `
  <div class="sentence-modal">
    <button class="sentence-close" type="button" aria-label="Close">×</button>
    <div class="sentence-modal-text"></div>
  </div>`;
document.body.appendChild(overlay);

const textEl = overlay.querySelector('.sentence-modal-text');
const close = () => {
  overlay.classList.remove('open');
  textEl.textContent = '';
};
overlay.querySelector('.sentence-close').addEventListener('click', close);
overlay.addEventListener('click', e => {
  if (e.target === overlay) close();
});

root.querySelectorAll('.sentence-row').forEach(row => {
  row.addEventListener('click', () => {
    textEl.textContent = row.textContent;
    overlay.classList.add('open');
  });
});

if (!window.__phonicsSentenceEscapeInstalled) {
  window.__phonicsSentenceEscapeInstalled = true;
  window.addEventListener('keydown', e => {
    document.querySelectorAll('.sentence-fullscreen.open').forEach(o => {
      if (e.key === 'Escape') {
        o.classList.remove('open');
        const tx = o.querySelector('.sentence-modal-text');
        if (tx) tx.textContent = '';
      }
    });
  });
}

